 document.querySelectorAll('[data-i18n-label]').forEach(el=>el.setAttribute('aria-label',t(el.dataset.i18nLabel)));
 const link=document.querySelector('#language');link.href=english?'?lang=ko':'?lang=en';link.textContent=english?'한국어':'EN';link.setAttribute('aria-label',t('switchLanguage'));link.hreflang=english?'ko':'en';
